
// CORS proxy fallback for GitHub Pages
const __originalFetch=window.fetch;
window.fetch=function(url,opts){
  opts=opts||{};
  // If URL is to androidapi.appmytv.com and we're on github.io
  if(typeof url==="string"&&url.indexOf("androidapi.appmytv.com")>-1&&location.hostname.indexOf("github.io")>-1){
    // Use allorigins proxy
    var proxyUrl="https://api.allorigins.win/raw?url="+encodeURIComponent(url);
    return __originalFetch(proxyUrl,opts).then(function(resp){
      if(!resp.ok){throw new Error("Proxy HTTP "+resp.status);}
      return resp;
    }).catch(function(e){
      // Fallback: try direct
      return __originalFetch(url,opts);
    });
  }
  // Also handle mytv-plus.net
  if(typeof url==="string"&&url.indexOf("mytv-plus.net")>-1&&location.hostname.indexOf("github.io")>-1){
    var proxyUrl2="https://api.allorigins.win/raw?url="+encodeURIComponent(url);
    return __originalFetch(proxyUrl2,opts).then(function(resp){
      if(!resp.ok){throw new Error("Proxy HTTP "+resp.status);}
      return resp;
    }).catch(function(e){
      return __originalFetch(url,opts);
    });
  }
  return __originalFetch(url,opts);
};
